<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { Plus, Search, Pencil } from '@lucide/vue'
import * as api from '../domain/api'
const props = defineProps<{ editable: boolean }>(); const emit = defineEmits<{ changed: [] }>()
const dictionaries = ref<api.Dictionary[]>([]); const selected = ref<api.Dictionary | null>(null); const query = ref(''); const termSearch = ref(''); const page = ref(1); const terms = ref<api.TermsPage | null>(null); const error = ref(''); const busy = ref(false); const newName = ref(''); const newValue = ref(''); const showNew = ref(false)
const filtered = computed(() => dictionaries.value.filter(d => d.name.toLowerCase().includes(query.value.toLowerCase())))
async function load() { busy.value = true; error.value = ''; try { dictionaries.value = await api.getDictionaries() } catch(e){ error.value = e instanceof Error ? e.message : 'Ошибка загрузки' } finally { busy.value = false } }
let request = 0
async function loadTerms() { if (!selected.value?.registered) { terms.value = null; return }; const current = ++request; error.value = ''; try { const data = await api.getTerms(selected.value.id, termSearch.value, page.value); if (current === request) terms.value = data } catch(e){ if (current === request) error.value = e instanceof Error ? e.message : 'Ошибка загрузки' } }
watch(selected, () => { page.value = 1; termSearch.value = ''; void loadTerms() }); watch([termSearch,page], () => { void loadTerms() })
async function addDictionary() { if (busy.value) return; busy.value = true; error.value = ''; try { const result = await api.addDictionary(newName.value); dictionaries.value = result.attributes; showNew.value = false; newName.value = ''; await load(); selected.value = dictionaries.value.find(d => d.id === result.id) ?? null; emit('changed') } catch(e){ error.value = e instanceof Error ? e.message : 'Не удалось создать' } finally { busy.value = false } }
async function addValue() { if (!selected.value || busy.value) return; busy.value = true; error.value = ''; try { await api.addTerm(selected.value.id,newValue.value); newValue.value = ''; await loadTerms(); emit('changed') } catch(e){ error.value = e instanceof Error ? e.message : 'Не удалось добавить значение' } finally { busy.value = false } }
async function rename(t: api.Term) { if (!selected.value || busy.value) return; const name = prompt(`Новое значение вместо «${t.name}». Оно изменится у всех товаров, использующих это значение (опубликованных: ${t.count}).`,t.name); if (name === null || name === t.name) return; if (!confirm('Изменить общее значение в справочнике? Отменить действие можно через историю.')) return; busy.value = true; error.value = ''; try { await api.renameTerm(selected.value.id,t,name); await loadTerms(); emit('changed') } catch(e){ error.value = e instanceof Error ? e.message : 'Не удалось изменить' } finally { busy.value = false } }
onMounted(load)
</script>
<template>
  <section><div class="page-heading"><div><h1>Характеристики</h1><p>Общие справочники значений каталога</p></div><button v-if="editable" class="button primary" @click="showNew = !showNew"><Plus :size="17" />Новый справочник</button></div><p v-if="error" role="alert" class="error-notice">{{ error }}</p><form v-if="showNew" class="filter-panel" @submit.prevent="addDictionary"><label>Название новой характеристики<input v-model="newName" placeholder="Например, Диаметр, мм" required maxlength="100" /></label><button type="submit" class="button primary" :disabled="busy">Создать справочник</button></form>
  <div class="dictionary-layout"><aside class="dictionary-list"><label class="search-field"><Search :size="17" /><input v-model="query" placeholder="Найти характеристику" aria-label="Поиск справочников" /></label><button v-for="d in filtered" :key="d.id" :class="{active:selected?.id===d.id}" @click="selected = d"><span>{{ d.name }}</span><small>{{ d.registered ? `${d.count} значений` : 'Не зарегистрирован' }}</small></button></aside><div class="dictionary-detail"><template v-if="selected"><h2>{{ selected.name }}</h2><p v-if="!selected.registered" class="info-box">Справочник есть в старых данных, но его таксономия не зарегистрирована в WordPress. Чтобы не повредить каталог, редактирование пока заблокировано.</p><template v-else><p class="muted">Значения используются в товарах. Переименование меняет общее значение, а не отдельную карточку.</p><label class="search-field"><Search :size="17" /><input v-model="termSearch" placeholder="Поиск значений" aria-label="Поиск значений справочника" /></label><form v-if="editable" class="inline-create" @submit.prevent="addValue"><input v-model="newValue" placeholder="Новое значение" aria-label="Новое значение характеристики" required /><button class="button" type="submit" :disabled="busy"><Plus :size="16" />Добавить</button></form><div class="term-list"><article v-for="t in terms?.items ?? []" :key="t.id"><span>{{ t.name }}</span><small>{{ t.count }} опубликованных товаров</small><button v-if="editable" class="icon-button" :disabled="busy" :aria-label="`Изменить значение ${t.name}`" @click="rename(t)"><Pencil :size="16" /></button></article></div><p v-if="terms && !terms.items.length" class="muted">Значения не найдены.</p><div v-if="terms" class="pagination"><button class="button" :disabled="page===1" @click="page--">←</button><span>{{ page }} / {{ Math.max(1,Math.ceil(terms.total/50)) }}</span><button class="button" :disabled="page*50>=terms.total" @click="page++">→</button></div></template></template><div v-else class="empty-state"><h2>Выберите характеристику</h2><p>Здесь появятся её значения и действия.</p></div></div></div></section>
</template>
